// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Avatar } from "@/registry/erbium/ui/avatar";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { AvatarFallback, AvatarImage } from \"@/registry/erbium/ui/avatar\";\nimport { Avatar } from \"@/registry/erbium/ui/avatar\";\n\nconst Example = (args: {\n  size: \"default\" | \"sm\" | \"lg\";\n  src: string;\n  alt: string;\n  fallback: string;\n  className: string;\n}) => (\n  <Avatar size={args.size} className={args.className}>\n    {args.src && <AvatarImage src={args.src} alt={args.alt} />}\n    <AvatarFallback>{args.fallback}</AvatarFallback>\n  </Avatar>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/avatar-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import FallbackExample from "./variants/fallback";

const FallbackSource = "import { AvatarFallback } from \"@/registry/erbium/ui/avatar\";\nimport { Avatar } from \"@/registry/erbium/ui/avatar\";\n\nconst Example = () => (\n  <Avatar>\n    <AvatarFallback>AN</AvatarFallback>\n  </Avatar>\n);\n\nexport default Example;\n";

import ImageExample from "./variants/image";

const ImageSource = "import { AvatarFallback, AvatarImage } from \"@/registry/erbium/ui/avatar\";\nimport { Avatar } from \"@/registry/erbium/ui/avatar\";\n\nconst Example = () => (\n  <Avatar>\n    <AvatarImage\n      src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2264%22%20height%3D%2264%22%20viewBox%3D%220%200%2064%2064%22%3E%3Crect%20width%3D%2264%22%20height%3D%2264%22%20rx%3D%2232%22%20fill%3D%22%23475569%22%2F%3E%3Ctext%20x%3D%2232%22%20y%3D%2233%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%20font-family%3D%22sans-serif%22%20font-size%3D%2222%22%20fill%3D%22white%22%3EJD%3C%2Ftext%3E%3C%2Fsvg%3E\"\n      alt=\"Profile\"\n    />\n    <AvatarFallback>AN</AvatarFallback>\n  </Avatar>\n);\n\nexport default Example;\n";

import BasicExample from "./variants/basic";

const BasicSource = "import AvatarDemo from \"../examples/upstream/avatar-basic\";\n\nconst Example = () => <AvatarDemo />;\n\nexport default Example;\n";

