const meta = {
  component: Avatar,
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "An image element with a fallback for representing the user.\n\n**Import:** `@/registry/erbium/ui/avatar`\n\n## Usage\n\n```tsx\nimport { Avatar, AvatarFallback, AvatarImage } from \"@/registry/erbium/ui/avatar\";\n```\n\n```tsx\n<Avatar>\n  <AvatarImage\n    src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2264%22%20height%3D%2264%22%20viewBox%3D%220%200%2064%2064%22%3E%3Crect%20width%3D%2264%22%20height%3D%2264%22%20rx%3D%2232%22%20fill%3D%22%23475569%22%2F%3E%3Ctext%20x%3D%2232%22%20y%3D%2233%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%20font-family%3D%22sans-serif%22%20font-size%3D%2222%22%20fill%3D%22white%22%3EJD%3C%2Ftext%3E%3C%2Fsvg%3E\"\n    alt=\"John Doe\"\n  />\n  <AvatarFallback>JD</AvatarFallback>\n</Avatar>\n```\n\n## Composition\n\nUse the following composition to build an `Avatar`:\n\nUse the following composition to build an `AvatarGroup`:\n\n```text\nAvatar\n├── AvatarImage\n├── AvatarFallback\n└── AvatarBadge\n```\n\n```text\nAvatarGroup\n├── Avatar\n│   ├── AvatarImage\n│   ├── AvatarFallback\n│   └── AvatarBadge\n├── Avatar\n│   ├── AvatarImage\n│   ├── AvatarFallback\n│   └── AvatarBadge\n└── AvatarGroupCount\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Avatar](https://base-ui.com/react/components/avatar)",
      },
    },
  },
} satisfies Meta<typeof Avatar>;

export default { ...meta, title: "Data display/Avatar",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

