  argTypes: {
    size: { control: "select", options: ["default", "sm", "lg"] },
    src: { control: "text" },
    alt: { control: "text" },
    fallback: { control: "text" },
    className: { control: "text" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
